use std::fs

fn is_int(t: string) -> bool {
    let mut digits = 0
    let mut i = 0
    for c in t.chars() {
        if c == '-' && i == 0 {
            i += 1
            continue
        }
        if c < '0' || c > '9' { return false }
        digits += 1
        i += 1
    }
    digits > 0
}

fn to_int(t: string) -> int {
    let mut neg = false
    let mut v = 0
    for c in t.chars() {
        if c == '-' {
            neg = true
        } else {
            v = v * 10 + (c as int - '0' as int)
        }
    }
    if neg { 0 - v } else { v }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" { continue }
        if is_int(t) {
            st.push(to_int(t))
            continue
        }
        let is_op = t == "+" || t == "-" || t == "*" || t == "/"
        if !is_op { return "error: token" }
        if st.len() < 2 { return "error: underflow" }
        let b = st[st.len() - 1]
        let a = st[st.len() - 2]
        st.pop()
        st.pop()
        if t == "+" { st.push(a + b) }
        if t == "-" { st.push(a - b) }
        if t == "*" { st.push(a * b) }
        if t == "/" {
            if b == 0 { return "error: divzero" }
            st.push(a / b)
        }
    }
    if st.len() != 1 { return "error: leftover" }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(eval(line.trim()))
    }
}

