use std::fs

fn is_int(t: string) -> bool {
    let mut start = 0
    if t.starts_with("-") { start = 1 }
    let n = t.len() as int
    if n <= start { return false }
    for c in t.chars().skip(start) {
        if c < '0' || c > '9' { return false }
    }
    true
}

fn to_int(t: string) -> int {
    let mut neg = false
    let mut v = 0
    for c in t.chars() {
        if c == '-' {
            neg = true
        } else {
            v = v * 10 + (c as int - '0' as int)
        }
    }
    if neg { 0 - v } else { v }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" { continue }
        if is_int(t) {
            st.push(to_int(t))
        } else if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 { return "error: underflow" }
            let b = st[st.len() - 1]
            let a = st[st.len() - 2]
            st.pop()
            st.pop()
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 { return "error: divzero" }
                st.push(a / b)
            }
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 { return "error: leftover" }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(eval(line.trim()))
    }
}
